import { createSignal, onCleanup, type Accessor } from 'solid-js';



export interface CopyToClipboardOptions {
	timeout?: number;
}

export interface CopyToClipboardResult {
	copy: (text: string) => Promise<boolean>;
	copied: Accessor<boolean>;
	error: Accessor<Error | null>;
}

function normalizeError(error: unknown): Error {
	return error instanceof Error ? error : new Error('Failed to copy');
}

/** 创建仅使用安全 Clipboard API 的复制状态。 */
export function createCopyToClipboard(options: CopyToClipboardOptions = {}): CopyToClipboardResult {
	const timeout = options.timeout ?? 2000;
	const [copied, setCopied] = createSignal(false);
	const [error, setError] = createSignal<Error | null>(null);
	let timer: ReturnType<typeof setTimeout> | undefined;
	let generation = 0;
	let disposed = false;

	onCleanup(() => {
		disposed = true;
		generation += 1;
		if (timer !== undefined) {
			clearTimeout(timer);
			timer = undefined;
		}
	});

	async function copy(text: string): Promise<boolean> {
		const operation = ++generation;
		if (timer !== undefined) {
			clearTimeout(timer);
			timer = undefined;
		}

		if (typeof navigator === 'undefined' || !navigator.clipboard?.writeText) {
			if (!disposed && operation === generation) {
				setCopied(false);
				setError(new Error('Clipboard API not available'));
			}
			return false;
		}

		try {
			await navigator.clipboard.writeText(text);
			if (disposed || operation !== generation) return true;
			setCopied(true);
			setError(null);
			if (timeout !== 0) {
				timer = setTimeout(() => {
					if (disposed || operation !== generation) return;
					timer = undefined;
					setCopied(false);
					setError(null);
				}, timeout);
			}
			return true;
		} catch (cause) {
			if (!disposed && operation === generation) {
				setCopied(false);
				setError(normalizeError(cause));
			}
			return false;
		}
	}

	return { copy, copied, error };
}
